/** [x, y] on the outline's 1000 × 1137 box for a latitude and longitude. */
export function projectIndia(lat, lon) {
  const x = ((lon * Math.PI) / 180 - 1.189658) * 1959.971026
  const y = (0.698122 - Math.log(Math.tan(Math.PI / 4 + (lat * Math.PI) / 360))) * 1959.971026
  return [x, y]
}
